{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "공원 내 가설건축물 점용허가가 공원 점용허가 세부기준에 맞는지",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "가설건축물의 점용허가 적합 여부는 가설건축물의 종류와 설치 목적에 따라 달라진다. 제10조제1항제2호에 따르면 영 제22조제8호에 따른 관리용 가설건축물은 공원 내에서 농업·임업·어업 또는 광업을 위한 작업장과 생산물의 건조를 위한 목적에 한하므로, 그 목적이면 기준에 맞고 그 밖의 목적이면 맞지 않는다. 제10조제1항제3호에 따르면 영 제22조제9호에 따른 가설건축물 중 \"창고시설\"은 위험물저장 및 처리시설 또는 그 부속용도에 해당하지 아니하는 건축물로서 창고, 냉동·냉장창고, 하역장의 목적에 한하고, 하나의 필지 연면적은 200제곱미터 이내로 하여야 한다. 또한 제10조제2항제4호에 따라 「건축법」 등 관계법령에 위배되지 아니하여야 한다.",
          "b_ids": "도시공원:제10조제1항제2호, 도시공원:제10조제1항제3호, 도시공원:제10조제2항제4호"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "가설건축물로 인해 새 진입도로를 만드는 것이 공원 점용허가 세부기준에 맞는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "가설건축물을 설치할 때 점용허가로 인하여 새로운 진입도로의 설치가 필요 없는 경우에 한하므로, 새 진입도로를 만들어야 하는 경우는 공원 점용허가 세부기준에 맞지 않는다.",
          "b_ids": "도시공원:제10조제2항제3호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
